function validate([s1, s2]) {
  for (const [name, text] of [['s1', s1], ['s2', s2]]) {
    if (typeof text !== 'string' || text.length < 1 || text.length > 100) return `${name} needs 1 to 100 characters.`;
    if (!/^[a-z]+$/.test(text)) return `${name} may contain only lowercase English letters.`;
  }
  return null;
}

