function shortestSuperstring(s1, s2) {
  if (s1.includes(s2)) {
    return s1;
  }
  if (s2.includes(s1)) {
    return s2;
  }
  const merge = (first, second) => {
    for (let overlap = Math.min(first.length, second.length) - 1; overlap > 0; overlap--) {
      if (first.endsWith(second.slice(0, overlap))) {
        return first + second.slice(overlap);
      }
    }
    return first + second;
  };
  const forward = merge(s1, s2);
  const backward = merge(s2, s1);
  return forward.length <= backward.length ? forward : backward;
}

