function shortestSuperstring(s1, s2) {
  // Place s2 at every offset relative to s1; keep the shortest placement whose overlapping letters agree.
  let shortest = s1 + s2;
  for (let shift = -s2.length; shift <= s1.length; shift++) {
    const from = Math.min(0, shift);
    const to = Math.max(s1.length, shift + s2.length);
    let built = '';
    let fits = true;
    for (let p = from; p < to; p++) {
      const a = p >= 0 && p < s1.length ? s1[p] : '';
      const b = p >= shift && p < shift + s2.length ? s2[p - shift] : '';
      if (a && b && a !== b) { fits = false; break; }
      built += a || b;
    }
    if (fits && built.length < shortest.length) shortest = built;
  }
  return shortest;
}

