function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const max = size === 'large' ? 100 : 6;
  // Few letters make long overlaps likely; a one-letter alphabet is kept rare.
  const letters = 'abcd'.slice(0, size === 'large' ? int(2, 4) : rand() < 0.1 ? 1 : int(2, 3));
  const word = (length) => {
    let text = '';
    for (let i = 0; i < length; i++) text += letters[int(0, letters.length - 1)];
    return text;
  };
  let s1 = word(int(size === 'large' ? 70 : 1, max));
  let s2;
  const mode = int(0, 3);
  if (mode === 0) {
    s2 = word(int(size === 'large' ? 70 : 1, max));
  } else if (mode === 1) {
    // One string inside the other.
    const start = int(0, s1.length - 1);
    s2 = s1.slice(start, int(start + 1, s1.length));
  } else if (mode === 2) {
    // s2 starts with a suffix of s1, so the two overlap.
    const shared = int(1, s1.length);
    s2 = (s1.slice(s1.length - shared) + word(max)).slice(0, int(shared, max));
  } else {
    // Two windows of one repeating pattern overlap in many ways.
    const pattern = word(int(2, 3));
    const repeat = (offset, length) => Array.from({ length }, (_, i) => pattern[(offset + i) % pattern.length]).join('');
    s1 = repeat(int(0, 2), s1.length);
    s2 = repeat(int(0, 2), int(size === 'large' ? 70 : 1, max));
  }
  return rand() < 0.5 ? [s1, s2] : [s2, s1];
}
